const fs = require('node:fs');
const path = require('node:path');

const ENDPOINT = 'http://127.0.0.1:49348/status';
const OUT_FILE = path.join(__dirname, 'results', 'status.json');

async function main() {
  const res = await fetch(ENDPOINT);
  if (!res.ok) {
    throw new Error(`Unexpected status: ${res.status}`);
  }
  const data = await res.json();

  fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
  fs.writeFileSync(OUT_FILE, JSON.stringify({ status: data.status }, null, 2) + '\n');

  console.log(`Wrote status=${data.status} to ${OUT_FILE}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

