const ENDPOINT = 'http://127.0.0.1:49348/status';
const OUT_FILE = path.join(__dirname, 'results', 'status.json');

async function main() {
  const res = await fetch(ENDPOINT);
  if (!res.ok) {
    throw new Error(`Unexpected status: ${res.status}`);
